private StandardToolTipTagFragmentGenerator standardToolTipTagFragmentGenerator;

    @Before 
    public void init(){
        standardToolTipTagFragmentGenerator = new StandardToolTipTagFragmentGenerator();
    }

    @Test 
    public void testGenerateToolTipFragment_NullText_ReturnsEscapedTitle(){
        String toolTipText = null;
        String result = standardToolTipTagFragmentGenerator.generateToolTipFragment(toolTipText);
        assertThat(result, containsString("title=\"\""));
    }

    @Test 
    public void testGenerateToolTipFragment_EmptyText_ReturnsEscapedTitle(){
        String toolTipText = "";
        String result = standardToolTipTagFragmentGenerator.generateToolTipFragment(toolTipText);
        assertThat(result, containsString("title=\"\""));
    }

    @Test 
    public void testGenerateToolTipFragment_SimpleText_ReturnsEscapedTitle(){
        String toolTipText = "Simple Text";
        String result = standardToolTipTagFragmentGenerator.generateToolTipFragment(toolTipText);
        assertThat(result, containsString("title=\"Simple Text\""));
    }

    @Test 
    public void testGenerateToolTipFragment_TextWithAmpersand_ReturnsEscapedTitle(){
        String toolTipText = "Text & More";
        String result = standardToolTipTagFragmentGenerator.generateToolTipFragment(toolTipText);
        assertThat(result, containsString("title=\"Text &amp; More\""));
    }

    @Test 
    public void testGenerateToolTipFragment_TextWithQuote_ReturnsEscapedTitle(){
        String toolTipText = "Text \" Quote";
        String result = standardToolTipTagFragmentGenerator.generateToolTipFragment(toolTipText);
        assertThat(result, containsString("title=\"Text &quot; Quote\""));
    }

    @Test 
    public void testGenerateToolTipFragment_TextWithLtGt_ReturnsEscapedTitle(){
        String toolTipText = "Text < >";
        String result = standardToolTipTagFragmentGenerator.generateToolTipFragment(toolTipText);
        assertThat(result, containsString("title=\"Text &lt; &gt;\""));
    }

    @Test 
    public void testGenerateToolTipFragment_LongText_ReturnsEscapedTitle(){
        StringBuilder longTextBuilder = new StringBuilder();
        for (int i = 0; i < 100; i++) {
            longTextBuilder.append("a");
        }
        String toolTipText = longTextBuilder.toString();
        String result = standardToolTipTagFragmentGenerator.generateToolTipFragment(toolTipText);
        assertThat(result, containsString("title=\"" + toolTipText + "\""));
    }
}
