public class ShapeUtilitiesTest{
private Line2D line1;
    private Line2D line2;
    private Ellipse2D ellipse1;
    private Ellipse2D ellipse2;
    private Arc2D arc1;
    private Arc2D arc2;
    private Polygon polygon1;
    private Polygon polygon2;
    private GeneralPath generalPath1;
    private GeneralPath generalPath2;

