    public void before(){
        line1 = new Line2D.Double(0, 0, 10, 10);
        line2 = new Line2D.Double(0, 0, 10, 10);
        ellipse1 = new Ellipse2D.Double(0, 0, 10, 10);
        ellipse2 = new Ellipse2D.Double(0, 0, 10, 10);
        arc1 = new Arc2D.Double(0, 0, 10, 10, 0, 90, Arc2D.OPEN);
        arc2 = new Arc2D.Double(0, 0, 10, 10, 0, 90, Arc2D.OPEN);
        polygon1 = new Polygon();
        polygon1.addPoint(0, 0);
        polygon1.addPoint(10, 0);
        polygon1.addPoint(5, 10);
        polygon2 = new Polygon();
        polygon2.addPoint(0, 0);
        polygon2.addPoint(10, 0);
        polygon2.addPoint(5, 10);
        generalPath1 = new GeneralPath();
        generalPath1.moveTo(0, 0);
        generalPath1.lineTo(10, 10);
        generalPath2 = new GeneralPath();
        generalPath2.moveTo(0, 0);
        generalPath2.lineTo(10, 10);
    }

    @Test
    public void testEqual_Line2D(){
        assertTrue(ShapeUtilities.equal(line1, line2));
        line2 = new Line2D.Double(0, 0, 10, 20);
        assertFalse(ShapeUtilities.equal(line1, line2));
    }

    @Test
    public void testEqual_Ellipse2D(){
        assertTrue(ShapeUtilities.equal(ellipse1, ellipse2));
        ellipse2 = new Ellipse2D.Double(0, 0, 10, 20);
        assertFalse(ShapeUtilities.equal(ellipse1, ellipse2));
    }

    @Test
    public void testEqual_Arc2D(){
        assertTrue(ShapeUtilities.equal(arc1, arc2));
        arc2 = new Arc2D.Double(0, 0, 10, 10, 0, 180, Arc2D.OPEN);
        assertFalse(ShapeUtilities.equal(arc1, arc2));
    }

    @Test
    public void testEqual_Polygon(){
        assertTrue(ShapeUtilities.equal(polygon1, polygon2));
        polygon2.addPoint(15, 15);
        assertFalse(ShapeUtilities.equal(polygon1, polygon2));
    }

    @Test
    public void testEqual_GeneralPath(){
        assertTrue(ShapeUtilities.equal(generalPath1, generalPath2));
        generalPath2.lineTo(20, 20);
        assertFalse(ShapeUtilities.equal(generalPath1, generalPath2));
    }

    @Test
    public void testEqual_Null(){
        assertFalse(ShapeUtilities.equal(null, line1));
        assertFalse(ShapeUtilities.equal(line1, null));
    }

    @Test
    public void testEqual_DifferentTypes(){
        assertFalse(ShapeUtilities.equal(line1, ellipse1));
        assertFalse(ShapeUtilities.equal(ellipse1, line1));
    }

    @Test
    public void testEqual_Rectangle2D(){
        Rectangle2D rectangle1 = new Rectangle2D.Double(0, 0, 10, 10);
        Rectangle2D rectangle2 = new Rectangle2D.Double(0, 0, 10, 10);
        assertTrue(ShapeUtilities.equal(rectangle1, rectangle2));
        rectangle2 = new Rectangle2D.Double(0, 0, 10, 20);
        assertFalse(ShapeUtilities.equal(rectangle1, rectangle2));
    }
}
