        assertEquals(ts.getRangeDescription(), clone.getRangeDescription());
        assertEquals(ts.getTimePeriodClass(), clone.getTimePeriodClass());
        assertEquals(ts.getMaximumItemCount(), clone.getMaximumItemCount());
        assertEquals(ts.getMaximumItemAge(), clone.getMaximumItemAge());
        assertTrue(clone.getItems().isEmpty());
