        Assert.assertEquals(1.0, item.getXValue(), 0.01);
        Assert.assertEquals(3.0, item.getYValue().doubleValue(), 0.01);
    }

    @Test
    public void testAddOrUpdate_duplicateXValuesAllowed() {
        series = new XYSeries("Test Series", true, true);
        series.add(1.0, 2.0);
